        setApprovingTarget(id);
        try {
            const res = await fetch(`/api/admin/moderation/${id}/approve`, {
                method: "POST"
            });
            const json = await res.json();
            if (json.success) {
                alert(json.message);
                // Loáº¡i bá» item khá»i danh sĂ¡ch
                setListings(prev => prev.filter(item => item.id !== id));
            } else {
                alert(json.error || "CĂ³ lá»—i xáº£y ra.");
            }
        } catch (e: any) {
            alert(e.message);
        } finally {
            setApprovingTarget(null);
        }
    };

    if (loading) {
        return <div className="w-full h-96 flex flex-col items-center justify-center gap-3"><Loader2 className="w-8 h-8 animate-spin text-primary" /> Äang táº£i tráº¡m kiá»ƒm duyá»‡t...</div>;
    }

