            </div>

            {listings.length === 0 ? (
                <div className="bg-white rounded-xl border border-dashed border-slate-300 p-12 text-center flex flex-col items-center">
                    <CheckCircle className="w-12 h-12 text-green-500 mb-3" />
                    <h3 className="text-lg font-medium text-slate-900">HoĂ n háº£o!</h3>
                    <p className="text-slate-500">Má»i tin Ä‘Äƒng trĂªn há»‡ thá»‘ng Ä‘á»u Ä‘Ă£ Ä‘Æ°á»£c xá»­ lĂ½.</p>
                </div>
            ) : (
