                    {listings.map(listing => (
                        <div key={listing.id} className={`bg-white rounded-xl border shadow-sm flex flex-col md:flex-row overflow-hidden ${listing.riskFlag ? "border-red-300 shadow-red-100" : "border-slate-200"}`}>

                            {/* Visual Match Section */}
                            <div className="md:w-1/3 bg-slate-50 p-4 border-b md:border-b-0 md:border-r border-slate-200 flex flex-col gap-4">
                                <div>
                                    <h4 className="text-xs font-semibold text-slate-500 uppercase flex items-center gap-1 mb-2"><FileText className="w-3 h-3" /> HĂ¬nh phĂ¡p lĂ½ (Sá»• Nhá»/Sá»• Há»“ng)</h4>
                                    <div className="bg-slate-200 h-24 rounded-lg flex items-center justify-center relative overflow-hidden border">
                                        {listing.legalDocuments.length > 0 ? (
                                            <img src={listing.legalDocuments[0]} alt="PhĂ¡p lĂ½" className="object-cover w-full h-full opacity-80" />
                                        ) : (
                                            <span className="text-xs text-slate-400">KhĂ´ng cĂ³ áº£nh</span>
                                        )}
                                    </div>
                                </div>
                                <div>
                                    <h4 className="text-xs font-semibold text-slate-500 uppercase flex items-center gap-1 mb-2"><ImageIcon className="w-3 h-3" /> HĂ¬nh hiá»‡n trÆ°á»ng Ä‘Äƒng tin</h4>
                                    <div className="bg-slate-200 h-24 rounded-lg flex items-center justify-center relative overflow-hidden border">
                                         {listing.realImages.length > 0 ? (
                                            <img src={listing.realImages[0]} alt="Hiá»‡n trÆ°á»ng" className="object-cover w-full h-full opacity-80" />
                                        ) : (
                                            <span className="text-xs text-slate-400">KhĂ´ng cĂ³ áº£nh</span>
                                        )}
                                    </div>
                                </div>
                            </div>

                            {/* Info Section */}
                            <div className="p-6 md:w-2/3 flex flex-col">
                                <div className="flex justify-between items-start mb-4">
                                    <div>
                                        <h3 className="text-lg font-bold text-slate-900 line-clamp-1">{listing.title}</h3>
                                        <p className="text-sm text-slate-500 mt-1">NgÆ°á»i Ä‘Äƒng: <span className="font-semibold text-slate-700">{listing.authorName}</span></p>
                                    </div>
                                    <div className="flex flex-col items-end gap-1">
                                        <span className="px-2.5 py-0.5 rounded-full bg-orange-100 text-orange-700 text-xs font-semibold whitespace-nowrap">
                                            {listing.status === "under_review" ? "Bá»‹ Cáº¯m Cá» Tá»± Äá»™ng" : "Chá» Duyá»‡t"}
                                        </span>
                                        {listing.fraudReportsCount > 0 && (
                                            <span className="flex items-center gap-1 text-xs text-red-600 font-medium">
                                                <AlertTriangle className="w-3 h-3" /> {listing.fraudReportsCount} report
