                                </div>

                                <div className="bg-slate-50 rounded-lg p-4 border border-slate-100 mb-6 flex-1">
                                    <h4 className="text-sm font-semibold mb-3 flex items-center gap-2">
                                        <MapPin className="w-4 h-4 text-primary" /> PhĂ¢n tĂ­ch Tá»a Äá»™ EXIF
                                    </h4>

                                    <div className="grid grid-cols-2 gap-4 text-sm mb-3">
                                        <div>
                                            <p className="text-slate-500 text-xs mb-1">Tá»a Ä‘á»™ ngáº§m tá»« Metadata File áº¢nh</p>
                                            <p className="font-mono text-slate-700 bg-white px-2 py-1 rounded border">
                                                {listing.exifCoordinates[0] !== 0 ? `${listing.exifCoordinates[1].toFixed(4)}, ${listing.exifCoordinates[0].toFixed(4)}` : "N/A (ChÆ°a báº­t vá»‹ trĂ­ M.áº¢nh)"}
                                            </p>
                                        </div>
                                        <div>
                                            <p className="text-slate-500 text-xs mb-1">Tá»a Ä‘á»™ ngáº§m Ä‘á»‹nh trĂªn Map App</p>
                                            <p className="font-mono text-slate-700 bg-white px-2 py-1 rounded border">
                                                {listing.inputCoordinates[0] !== 0 ? `${listing.inputCoordinates[1].toFixed(4)}, ${listing.inputCoordinates[0].toFixed(4)}` : "KhĂ´ng cĂ³"}
                                            </p>
                                        </div>
                                    </div>

                                    {listing.distanceDeviationMeters >= 0 ? (
                                        <div className={`p-3 rounded-md text-sm font-medium flex items-center gap-2 border ${listing.riskFlag ? "bg-red-50 text-red-700 border-red-200" : "bg-green-50 text-green-700 border-green-200"}`}>
