                                        <Eye className="w-4 h-4" /> Xem chi tiáº¿t
                                    </button>
                                    <button className="flex-1 py-2 px-4 rounded-lg border border-red-200 hover:bg-red-50 text-red-600 text-sm font-medium transition-colors">
                                        Tá»« Chá»‘i / Ban
                                    </button>
                                    <button 
                                        onClick={() => handleApprove(listing.id)}
                                        disabled={approvingTarget === listing.id}
                                        className="flex-1 py-2 px-4 rounded-lg bg-green-500 hover:bg-green-600 text-white text-sm font-semibold transition-colors flex items-center justify-center shadow-lg shadow-green-500/30 disabled:opacity-50"
                                    >
                                        {approvingTarget === listing.id ? <Loader2 className="w-4 h-4 animate-spin" /> : "Approve & ÄĂ³ng Dáº¥u Verified"}
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

import { NextRequest, NextResponse } from "next/server";
import mongoose from "mongoose";
import dbConnect from "@/lib/db";
import { Appointment } from "@/models/Appointment";
import { Property } from "@/models/Property";
import { auth } from "@/app/api/auth/[...nextauth]/route";

/**
 * Controller: KhĂ¡ch hĂ ng xĂ¡c nháº­n "ÄĂ£ Xem NhĂ " (O2O Completion & Review Module)
 * Theo yĂªu cáº§u: Sá»­ dá»¥ng Mongoose Transactions Ä‘á»ƒ Ä‘áº£m báº£o tĂ­nh toĂ n váº¹n.
 */
export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await auth();
    // 1. Kiá»ƒm tra xĂ¡c thá»±c User
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Await params object for Next.js 15+ dynamic route params
    const resolvedParams = await params;
    const appointmentId = resolvedParams.id;

    // 2. Tham sá»‘ tá»« body (vĂ­ dá»¥ tá»« Form ÄĂ¡nh GiĂ¡ mĂ  ngÆ°á»i mua gá»­i lĂªn)
    const body = await req.json();
    const { rating, notes, isFraud } = body;

    await dbConnect();

    // 3. Khá»Ÿi táº¡o Mongoose Session & Transaction
    const mongooseSession = await mongoose.startSession();
    mongooseSession.startTransaction();

    try {
      // 4a. TĂ¬m Appointment vĂ  validate (KhĂ³a láº¡i cho transaction)
      const appointment = await Appointment.findById(appointmentId).session(mongooseSession);
      if (!appointment) {
        throw new Error("Lá»‹ch háº¹n khĂ´ng tá»“n táº¡i");
      }

      // Äáº£m báº£o chá»‰ cĂ³ Buyer cá»§a lá»‹ch háº¹n nĂ y má»›i Ä‘Æ°á»£c báº¥m Confirm
      if (appointment.buyerId !== session.user.id) {
        throw new Error("Báº¡n khĂ´ng cĂ³ quyá»n thá»±c hiá»‡n hĂ nh Ä‘á»™ng nĂ y");
      }

      // 4b. Cáº­p nháº­t Appointment (HoĂ n thĂ nh háº¹n & Ghi nháº­n Ä‘Ă¡nh giĂ¡)
      appointment.status = "completed";
      appointment.reviewStatus = "submitted";
      appointment.rating = rating;
      appointment.notes = notes;
      appointment.isFraudReported = isFraud === true;
      await appointment.save({ session: mongooseSession });

      // 5. Xá»­ lĂ½ logic Fraud (Lá»«a Ä‘áº£o / Tin áº£o)
      let needsAdminWarning = false;
      let propertyFlagsCount = 0;

      if (isFraud) {
        // TĂ¬m Property liĂªn quan vĂ  tÄƒng sá»‘ lÆ°á»£ng Fraud Reports
        const property = await Property.findById(appointment.propertyId).session(mongooseSession);

        if (property) {
          property.fraudReports = (property.fraudReports || 0) + 1;
          propertyFlagsCount = property.fraudReports;

          // RĂ ng buá»™c: Náº¿u bá»‹ bĂ¡o cĂ¡o >= 3 láº§n -> Flag Under Review
          if (property.fraudReports >= 3) {
            property.status = "under_review";
            needsAdminWarning = true;
          }
          await property.save({ session: mongooseSession });
        }
      }

      // 6. Commit Transaction thay vĂ¬ auto-save Ä‘Æ¡n láº»
      await mongooseSession.commitTransaction();
      mongooseSession.endSession();

      // 7. (Optional/Background) Gá»­i Email cho Admin náº¿u cáº§n thiáº¿t
      if (needsAdminWarning) {
        // Pseudo-code System Alarm
        console.warn(`[SYSTEM ALERT] Property ${appointment.propertyId} has reached ${propertyFlagsCount} fraud reports. It is now Under Review.`);
        // await sendEmailToAdmin({ subject: "Canh bao tin tuc ao", id: appointment.propertyId });
      }

      return NextResponse.json({ 
        success: true, 
        message: "CĂ¡m Æ¡n báº¡n Ä‘Ă£ xĂ¡c nháº­n buá»•i xem nhĂ  vĂ  gá»­i Ä‘Ă¡nh giĂ¡ thĂ nh cĂ´ng." 
      }, { status: 200 });

    } catch (transactionError: any) {
      // 8. Náº¿u quĂ¡ trĂ¬nh update cĂ³ lá»—i (Database down, Validation fail, ...), Rollback táº¥t cáº£
      await mongooseSession.abortTransaction();
      mongooseSession.endSession();
      throw transactionError; // Pass down to outter block
    }

  } catch (error: any) {
    console.error("Complete Appointment Error:", error);
    return NextResponse.json(
      { error: error.message || "Lá»—i mĂ¡y chá»§ ná»™i bá»™. Vui lĂ²ng thá»­ láº¡i sau." },
      { status: 500 }
    );
  }
}

import NextAuth, { DefaultSession } from "next-auth";

declare module "next-auth" {
  /**
   * Returned by `useSession`, `getSession` and received as a prop on the `SessionProvider` React Context
   */
  interface Session {
    user: {
      /** The user's postal id. */
      id: string;
      /** The user's role. */
      role: string;

    } & DefaultSession["user"];
  }

  interface User {
      role?: string;
  }
}

declare module "next-auth/jwt" {
  /** Returned by the `jwt` callback and `getToken`, when using JWT sessions */
  interface JWT {
    /** The user's role. */
    role?: string;
  }
}
